private void close(String code, long offset, int ev, int pkt) {
    if (closed) {
        return;
    }
    closed = true;
    closeEvent = ev;
    closePacket = pkt;
    closeOffset = offset;
    closeCode = code;
}

private void accept(int level, long pn, Long epoch) {
    final Set<Long> set = seen.get(level);
    final long value = pn;
    set.add(value);
    journal.add(new Runnable() {
        @Override
        public void run() {
            set.remove(value);
        }
    });
    if (pn > largest[level]) {
        final int lvl = level;
        final long old = largest[level];
        largest[level] = pn;
        journal.add(new Runnable() {
            @Override
            public void run() {
                largest[lvl] = old;
            }
        });
    }
    if (level != 2 || epoch == null) {
        return;
    }
    long[] st = epochs.get(epoch);
    if (st == null) {
        st = new long[] {pn, pn, 1};
        final long key = epoch;
        epochs.put(key, st);
        journal.add(new Runnable() {
            @Override
            public void run() {
                epochs.remove(key);
            }
        });
    } else {
        final long[] f = st;
        final long oMin = f[0];
        final long oMax = f[1];
        final long oCount = f[2];
        journal.add(new Runnable() {
            @Override
            public void run() {
                f[0] = oMin;
                f[1] = oMax;
                f[2] = oCount;
            }
        });
        if (pn < st[0]) {
            st[0] = pn;
        }
        if (pn > st[1]) {
            st[1] = pn;
        }
        st[2]++;
    }
    if (epoch == scal[S_EPOCH] + 1) {
        setScalar(S_EPOCH, epoch);
    }
}

